    public static void main(String[] args) {
        int[] marks = {72, 88, 91, 65, 80};
        int sum = 0;
        int max = marks[0];
        for (int mark : marks) {
            sum += mark;
            if (mark > max) max = mark;
        }
        System.out.println("sum=" + sum);
        System.out.printf("avg=%.1f%n", (double) sum / marks.length);
        System.out.println("max=" + max);
    }
}

import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[][] grid = {{1, 2}, {3, 4, 5}, {6}};
        for (int r = 0; r < grid.length; r++) {
            int rowSum = 0;
            for (int value : grid[r]) rowSum += value;
            System.out.println("row " + r + ": " + Arrays.toString(grid[r]) + " sum=" + rowSum);
        }
        System.out.println(grid.length + " rows, last row length " + grid[grid.length - 1].length);
    }
}

