import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) nums[i] = sc.nextInt();
        long sum = 0;
        int max = nums[0];
        for (int value : nums) {
            sum += value;
            if (value > max) max = value;
        }
        System.out.println(sum);
        System.out.println(max);
    }
}
